$ctrl.payScheduleMap.filter(paySchedule => {
    const relatedPaySchedule = $ctrl.paySchedules.find(
        schedule => schedule.Id === paySchedule.value
    );

    return relatedPaySchedule && relatedPaySchedule.CompanyId === $ctrl.globalSelectedCompany.companyId;
});

$ctrl.payPeriodMap.filter(payPeriod => {
    // 1. Resolve full pay period entity from map value ID
    const relatedPayPeriod = $ctrl.payPeriods?.find(
        period => period.Id === payPeriod.value
    );

    if (!relatedPayPeriod) return false;

    const runType = $ctrl.selectedType;
    const currentCompanyId = $ctrl.globalSelectedCompany?.companyId;

    // 2. REGULAR run, OR OFFCYCLE run scoped to a specific Pay Schedule
    if (runType === "REGULAR" || (runType === "OFFCYCLE" && $ctrl.selectedPaySchedule)) {
        return relatedPayPeriod.PayScheduleId === $ctrl.selectedPaySchedule &&
            $ctrl.paySchedules?.some(
                schedule => schedule.Id === relatedPayPeriod.PayScheduleId &&
                    schedule.CompanyId === currentCompanyId
            );
    }

    // Resolve companyId with fallback to PaySchedule for OFFCYCLE/TERMINATION
    const scheduleCompanyId = $ctrl.paySchedules?.find(s => s.Id === relatedPayPeriod.PayScheduleId)?.CompanyId;
    const effectiveCompanyId = relatedPayPeriod.CompanyId ?? scheduleCompanyId;

    // 3. OFFCYCLE run without a selected Pay Schedule
    if (runType === "OFFCYCLE" && !$ctrl.selectedPaySchedule) {
        return Boolean(relatedPayPeriod.OffCycle) &&
            effectiveCompanyId === currentCompanyId;
    }

    // 4. TERMINATION run
    if (runType === "TERMINATION") {
        return Boolean(relatedPayPeriod.OffCycle) &&
            effectiveCompanyId === currentCompanyId;
    }

    return false;
});

