const limit = 1000;
const offset = 0;

return $ctrl.payrollAppApi[endpoint](
    { limit: limit, offset: offset },
    { headers: $ctrl.authCookies.setHeaders() }
)
    .then((result) => result.data[entity])
    .catch((reason) => {
        $ctrl.utils.toast(reason.data.message, reason.data.result);
        throw reason;
    });

const result = {};
for (const key in form) {
    if (form.hasOwnProperty(key)) {
        const titleCaseKey = key.charAt(0).toUpperCase() + key.slice(1);

        if (form[key] === "") continue;

        // Resets
        if (key === "runType" && form[key] !== "OFFCYCLE") $ctrl.utils.resetDependentFields(["offCycleReason"], form);

        if ((key === "offCycle" || key === "payScheduleId" || key === "startDate" || key === "endDate" || key === "payDate" || key === "payPeriodId" || key === "runType" || key === "finalPayEligibleWorker") && method === "PUT") continue;

        if ((/^(is|need|with|can|allow|active|salaried|enabled|final)/i.test(key) || key.toLowerCase() === "employercontribution") && method === "POST" && key !== "finalPayEligibleWorker") {
            result[titleCaseKey] = form[key] || false;
        } else if (key.includes("Date") && form[key]) {
            result[titleCaseKey] = $ctrl.utils.parseDate(form[key]);
        } else {
            result[titleCaseKey] = form[key];
        }
    }
}
return result;

if (method === "POST") $ctrl.isInserting = true;
if (method === "PUT") $ctrl.isUpdating = true;

$ctrl.payrollAppApi[endpoint](
    {},
    {
        ...$ctrl.buildRequestBody(form, method),
        ...(method === "PUT" ? { "Id": $ctrl.selectedEntity.Id } : {}),
        ...(method === "PUT" && $ctrl.selectedEntity.Entity === "Position" ? { "BaseRateUnit": $ctrl.selectedEntity.Detail.BaseRateUnit } : {}),
    },
    { headers: $ctrl.authCookies.setHeaders() }
).then(result => {
    $ctrl.utils.toast(`Successfully ${$ctrl.isInserting ? "added" : "edited"} ${entityName}`, result.data.result);

    if ($ctrl.isInserting) $ctrl.setIsAdding();
    if ($ctrl.isUpdating) $ctrl.setIsEditing();

    $ctrl.tempSelectedType = $ctrl.selectedType;
    $ctrl.getAllEntities();
    $ctrl.utils.resetForm(form);

}).catch(reason => {
    $ctrl.utils.toast(reason.data.message, reason.data.result);
}).finally(() => {
    if ($ctrl.isInserting) $ctrl.isInserting = false;
    if ($ctrl.isUpdating) $ctrl.isUpdating = false;
});

const toBeDeletedEntity = $ctrl.selectedEntityName;
let isConfirmed;
$ctrl.isDeleting = true;

await $ctrl.$modal.open("delete-entity-modal", {
    props:
    {
        EntityName: $ctrl.selectedEntityName,
        EntityDetails: $ctrl.selectedEntityDetails
    }
}).then(response => isConfirmed = response.result === "ok");

if (isConfirmed) {
    $ctrl.payrollAppApi[endpoint](
        {
            userId: $ctrl.authCookies.activeUser.id,
            id: $ctrl.selectedEntity.Id
        },
        { headers: $ctrl.authCookies.setHeaders() }
    ).then(result => {
        $ctrl.tempSelectedType = $ctrl.selectedType;
        $ctrl.getAllEntities();
        $ctrl.utils.toast(`Successfully deleted ${toBeDeletedEntity}`, result.data.result);
        $ctrl.isDeleting = false;
    }).catch(reason => {
        $ctrl.utils.toast(reason.data.message, reason.data.result);
        $ctrl.isDeleting = false;
    }).finally(() => {
        $ctrl.isDeleting = false;
    });

} else {
    $ctrl.isDeleting = false;
}

if ($ctrl.$env.current.name === "prod" && !$ctrl.$cookies.get("id_token")) {
    window.location.href = "#!/user_login";
    return;
}

const usrIsAdmin = await $ctrl.authService.redirectWorker();
if(!usrIsAdmin) return;

if ($ctrl.isFirstLoad) $ctrl.authCookies.getAuthToken().then(() => $ctrl.isFirstLoad = false);

// Resets
$ctrl.currentPage = 1;
$ctrl.entityUiStateService.initializationError = null;

$ctrl.selectedEntityName = null;
$ctrl.selectedEntity = null;
$ctrl.selectedEntityDetails = "";

$ctrl.selectedPaySchedule = null;
$ctrl.selectedPayPeriod = null;

// Main
$ctrl.isGettingEntities = true;

Promise.all([
    $ctrl.getData('lonti_app_payroll_service_user_SelectAllUser', 'user'),
    $ctrl.getData('lonti_app_payroll_service_company_SelectAllCompany', 'company'),
    $ctrl.getData('lonti_app_payroll_service_pay_period_SelectAllPayPeriod', 'payperiod'),
    $ctrl.getData('lonti_app_payroll_service_payroll_run_SelectAllPayrollRun', 'payrollrun'),
    $ctrl.getData('lonti_app_payroll_service_pay_schedule_SelectAllPaySchedule', 'payschedule'),
    $ctrl.getData('lonti_app_payroll_service_worker_SelectAllWorker', 'worker'),
    $ctrl.getData('lonti_app_payroll_service_reporting_SelectAllEntityEffectivity', 'entityeffectivity'),
]).then(results => $ctrl.$timeout(() => {
    const [
        users,
        companies,
        payPeriods,
        payrollRuns,
        paySchedules,
        workers,
        entityEffectivities,
    ] = results;

    $ctrl.dataHandlers.setContext($ctrl);

    $ctrl.dataHandlers.processData(users, {
        ctrlDataName: 'users',
        ctrlColumnName: 'userColumns',
        removeFields: ["Deleted"],
        replaceUserIds: true,
        hideColumns: true
    });

    $ctrl.dataHandlers.processData(companies, {
        ctrlDataName: 'companies',
        removeFields: ["Deleted"],
        replaceUserIds: true,
        hideColumns: true
    });

    $ctrl.dataHandlers.processData(payPeriods, {
        ctrlDataName: 'payPeriods',
        ctrlColumnName: 'payPeriodColumns',
        removeFields: ["Deleted"],
        replaceUserIds: true,
        hideColumns: true
    });

    $ctrl.dataHandlers.processData(entityEffectivities, {
        ctrlDataName: 'entityEffectivities',
        ctrlColumnName: 'entityEffectivityColumns',
        removeFields: ["Deleted"],
        replaceUserIds: true,
        hideColumns: true
    });

    $ctrl.dataHandlers.processData(workers, {
        ctrlDataName: 'workers'
    });

    $ctrl.dataHandlers.processData(payrollRuns, {
        ctrlDataName: 'payrollRuns',
        ctrlColumnName: 'payrollRunColumns',
        removeFields: ["Deleted"],
        replaceUserIds: true,
        hideColumns: true
    });

    $ctrl.dataHandlers.processData(paySchedules, {
        ctrlDataName: 'paySchedules',
    });

    $ctrl.dataHandlers.processData(companies, {
        mapToLabelValue: 'companyMap',
        entityList: $ctrl.companies,
        mapLabelKey: 'LegalName',
        mapValueKey: 'Id'
    });

    $ctrl.dataHandlers.processData(paySchedules, {
        mapToLabelValue: 'payScheduleMap',
        entityList: paySchedules,
        mapLabelKey: 'DisplayName',
        mapValueKey: 'Id'
    });

    $ctrl.dataHandlers.processData(payPeriods, {
        mapToLabelValue: 'payPeriodMap',
        entityList: payPeriods,
        mapLabelKey: 'DisplayName',
        mapValueKey: 'Id'
    });

    $ctrl.dataHandlers.processData(users, {
        mapToLabelValue: 'workerMap',
        entityList: users,
        mapLabelKey: ['FirstName', 'LastName'],
        mapValueKey: 'WorkerId'
    });

    $ctrl.setTable($ctrl.storedTab ? $ctrl.storedTab : 1);
    if (!$ctrl.globalSelectedCompany.companyMap.length > 0) $ctrl.globalSelectedCompany.companyMap = $ctrl.companyMap.map(obj => ({...obj}));
    $ctrl.globalSelectedCompany.setMenuItems();

    if ($ctrl.tempSelectedType) {
        $ctrl.selectedType = $ctrl.tempSelectedType;
        $ctrl.tempSelectedType = null;
    } else $ctrl.selectedType = "REGULAR"

    if ($ctrl.globalSelectedCompany.companyId) $ctrl.handleCompanyChange();
    if ($ctrl.globalSelectedCompany.companyId && $ctrl.storedTab === 2) $ctrl.handleRunTypeChange();

    $ctrl.isGettingEntities = false;
}, 500)).catch(error => {
        $ctrl.entityUiStateService.initializationError = error.data?.message || "Failed to load required data.";
        $ctrl.utils.toast($ctrl.entityUiStateService.initializationError, "ERROR");
        console.error("Data loading failed:", error);
}).finally(() => $ctrl.isGettingEntities = false);

$ctrl.isUpdating = true;
const entity = $ctrl.selectedEntity.Entity;

switch ($ctrl.storedTab) {
    default:
        $ctrl.sendData(
            entity !== "Pay Schedule"
            ? "lonti_app_payroll_service_" + entity.toLowerCase() + "_Update" + entity
            : "lonti_app_payroll_service_pay_schedule_UpdatePaySchedule",
            $ctrl.form,
            $ctrl.selectedEntity.Name,
            "PUT"
        );
        break;

    case 2:
        $ctrl.sendData(
            "lonti_app_payroll_service_payroll_run_UpdatePayrollRun",
            $ctrl.form1,
            $ctrl.selectedEntity.DisplayName,
            "PUT"
        );
        break;
}

const entity = $ctrl.selectedEntity.Entity;
switch ($ctrl.storedTab) {
    default:
        $ctrl.deleteData(entity !== "Pay Schedule"
            ? "lonti_app_payroll_service_" + entity.toLowerCase() + "_Delete" + entity
            : "lonti_app_payroll_service_pay_schedule_DeletePaySchedule");
        break;

    case 2:
        $ctrl.deleteData("lonti_app_payroll_service_payroll_run_DeletePayrollRun");
        break;
}

// Main
if (row === undefined) {
    $ctrl.isEditingEntity = false;
    $ctrl.isEditingPayrollRun = false;

    $ctrl.selectedEntity = null;
    $ctrl.selectedEntityName = null;
    $ctrl.selectedEntityDetails = "";

    if (document.getElementById("details")) document.getElementById("details").innerHTML = "";
    return;
}

$ctrl.selectedEntity = row;

if ($ctrl.isEditingEntity || $ctrl.isEditingPayrollRun) {
    $ctrl.utils.resetForm($ctrl.form);
    $ctrl.utils.resetForm($ctrl.form1);
}

$ctrl.selectedEntityDetails = "";

setEntityDetails();
waitForElementAndInject();
setEntityName();

if ($ctrl.storedTab === 2) {
    $ctrl.handlers.payroll_run.setSelectedPayrollRunReviewJobs(row.Id);
}
// End of Main

// Functions
function setEntityName() {
    for (const key in row) {
        if ((row.hasOwnProperty(key) && key.toLowerCase().includes("name")) || ((row.hasOwnProperty(key) && key.toLowerCase().includes("title")))) {
            $ctrl.selectedEntityName = row[key] || "Deleted";
            break;
        }
    }
}

function setEntityDetails() {
    for (const [key, value] of Object.entries(row)) {
        if (key.startsWith("$$")) continue;
        if (key.includes("Company")) continue;
        if (key.includes("YesNo")) continue;
        if ((key.includes("Id") && key !== "Id") || value === undefined) continue;
        if (key === "CreatedDate" || key === "AnnualPayPeriods") $ctrl.selectedEntityDetails += `<br><hr>`;

        if (key.includes("CalculationMethodId")) {
            $ctrl.selectedEntityDetails +=
                `
                <div style="display: flex; width: 100%;">
                    <div style="font-weight: bold;">${key}</div>
                    <div style="flex-grow: 1;"></div>
                    <div>${value === 1 ? "FLAT" : "PERCENT"}</div>
                </div>
                <hr>
                `;
            continue;
        }

        if (typeof value === "boolean") {
            $ctrl.selectedEntityDetails +=
                `
                <div style="display: flex; width: 100%; align-items: center;">
                    <div style="font-weight: bold; flex-shrink: 0;">${key}</div>
                    <div style="flex-grow: 1;"></div>
                    <div class="status-indicator ${value ? 'yes' : 'no'}">
                        ${value ? 'YES' : 'NO'}
                    </div>
                </div>
                <hr>
                `;
            continue;
        }

        if (typeof value === "object") continue;

        $ctrl.selectedEntityDetails +=
            `
            <div style="display: flex; width: 100%;">
                <div style="font-weight: bold;">${key}</div>
                <div style="flex-grow: 1;"></div>
                <div>${value}</div>
            </div>
            <hr>
            `;

            // Parsing date for easier viewing, but it seems there is a bug with time, so disabling for now.
            // <div>${typeof key === "string" && key.includes("Date") ? $ctrl.parseDate(value) : value}</div>

        if (key === "DayStartTime") $ctrl.selectedEntityDetails += `<br>`;
    }
}

function waitForElementAndInject() {
    let element = document.getElementById("details");

    if (element) {
        element.innerHTML = $ctrl.selectedEntityDetails;
    } else {
        $ctrl.$timeout(waitForElementAndInject, 100);
    }
}

if (selectedTab === undefined) null;

// Reset
$ctrl.selectedEntity = null;
$ctrl.selectedEntityName = null;
$ctrl.selectedEntityDetails = "";

$ctrl.isEditingEntity = false;
$ctrl.isEditingPayrollRun = false;

$ctrl.currentPage = 1;

$ctrl.storedTab = selectedTab;

switch (selectedTab) {
    default:
        $ctrl.tableData = $ctrl.entityEffectivities;
        $ctrl.tableColumns = $ctrl.entityEffectivityColumns;
        $ctrl.filteredTableData = $ctrl.tableData;
        if ($ctrl.globalSelectedCompany.companyId) $ctrl.handleCompanyChange();
        break;

    case 2:
        $ctrl.tableData = $ctrl.payrollRuns;
        $ctrl.tableColumns = $ctrl.payrollRunColumns;
        $ctrl.filteredTableData = $ctrl.tableData;
        $ctrl.runTypeMap = [
            { "label": "REGULAR", "value": "REGULAR" },
            { "label": "OFF-CYCLE", "value": "OFFCYCLE" },
            { "label": "TERMINATION", "value": "TERMINATION" }
        ];
        if ($ctrl.globalSelectedCompany.companyId) $ctrl.handleCompanyChange();
        break;
}

if ($ctrl.selectedType) $ctrl.handleRunTypeChange();

if ($ctrl.isEditingEntity || $ctrl.isEditingPayrollRun) {
    $ctrl.setIsEditing();
    return;
} else {
    $ctrl.selectedEntity = null;
    $ctrl.selectedEntityName = null;
    $ctrl.selectedEntityDetails = "";
}

switch ($ctrl.storedTab) {
    default:
        $ctrl.utils.resetForm($ctrl.form);
        break;

    case 2:
        $ctrl.utils.resetForm($ctrl.form1);
        break;
}

if ($ctrl.isEditingEntity || $ctrl.isEditingPayrollRun) {
    $ctrl.utils.resetForm($ctrl.form);
    $ctrl.utils.resetForm($ctrl.form1);
}

switch ($ctrl.storedTab) {
    default:
        $ctrl.isEditingEntity = !$ctrl.isEditingEntity;
        break;

    case 2:
        $ctrl.isEditingPayrollRun = !$ctrl.isEditingPayrollRun;
        break;
}

$ctrl.setInputValues();

if (!$ctrl.selectedEntity) return;
if (Object.keys($ctrl.selectedEntity).length === 0) return;

switch ($ctrl.storedTab) {
    default:
        useExistingValuesAsInputValues($ctrl.form);
        break;

    case 2:
        useExistingValuesAsInputValues($ctrl.form1);
        break;
}

function useExistingValuesAsInputValues(form) {
    const obj = $ctrl.selectedEntity;

    for (let key in form) {
        const adjustedKey = key.charAt(0).toUpperCase() + key.slice(1);
        // if (key.includes("Date")) form[key] = obj.hasOwnProperty(adjustedKey) ? $ctrl.parseDate(obj[adjustedKey]) : undefined;
        form[key] = obj.hasOwnProperty(adjustedKey) ? obj[adjustedKey] : undefined;
    }
}

const currentCompanyId = $ctrl.globalSelectedCompany?.companyId;

if (!currentCompanyId || !$ctrl.tableData || $ctrl.tableData.length === 0) return;

// Resets
$ctrl.isEditingEntity = false;
$ctrl.isEditingPayrollRun = false;

// Tab 1: Entity-based scoping (Deductions, Taxes, etc.)
if ($ctrl.storedTab === 1) {
    $ctrl.filteredTableData = $ctrl.tableData.filter(row => {
        if (!["Deduction", "Tax"].includes(row.Entity)) {
            return row.Detail?.CompanyId === currentCompanyId;
        }
        if (row.Entity === "Deduction") {
            const worker = $ctrl.workers?.find(w => w.Id === row.Detail?.WorkerId);
            return worker?.CompanyId === currentCompanyId;
        }
        return true;
    });
}
// Tab 2: Payroll Runs scoping
else if ($ctrl.storedTab === 2) {
    if ($ctrl.selectedType) {
        // Triggers for ALL run types (REGULAR, OFFCYCLE, TERMINATION)
        $ctrl.handleRunTypeChange();
    } else {
        // Fallback: Scope all runs when no run type filter is explicitly selected
        $ctrl.filteredTableData = $ctrl.tableData.filter(row => {
            const payPeriod = $ctrl.payPeriods?.find(p => p.Id === row.PayPeriodId);
            if (!payPeriod) return false;

            // REGULAR: Scope via PaySchedule -> CompanyId
            if (row.RunType === "REGULAR") {
                const paySchedule = $ctrl.paySchedules?.find(s => s.Id === payPeriod.PayScheduleId);
                return paySchedule?.CompanyId === currentCompanyId;
            }

            // OFFCYCLE / TERMINATION: Scope via PayPeriod -> CompanyId (or fallback to PaySchedule)
            const scheduleCompanyId = $ctrl.paySchedules?.find(s => s.Id === payPeriod.PayScheduleId)?.CompanyId;
            const companyId = payPeriod.CompanyId ?? scheduleCompanyId;

            return companyId === currentCompanyId;
        });
    }
}

$ctrl.filterTarget = null;

if ($ctrl.selectedEntityName) {
    $ctrl.selectedEntity = {};
    $ctrl.selectedEntityName = "";
    $ctrl.selectedEntityDetails = "";
}

const currentCompanyId = $ctrl.globalSelectedCompany?.companyId;

if ($ctrl.storedTab === 2) {
    $ctrl.filteredTableData = $ctrl.tableData.filter(row => {
        if (row.RunType !== $ctrl.selectedType) return false;

        // 1. Safe Pay Period Lookup
        const payPeriod = $ctrl.payPeriods?.find(p => p.Id === row.PayPeriodId);
        if (!payPeriod) return false;

        // 2. Regular Runs: Scope via PaySchedule's CompanyId
        if ($ctrl.selectedType === "REGULAR") {
            const paySchedule = $ctrl.paySchedules?.find(s => s.Id === payPeriod.PayScheduleId);
            return paySchedule?.CompanyId === currentCompanyId;
        }

        // 3. Off-Cycle / Termination Runs: Check direct CompanyId or fallback to PaySchedule
        const scheduleCompanyId = $ctrl.paySchedules?.find(s => s.Id === payPeriod.PayScheduleId)?.CompanyId;
        const companyId = payPeriod.CompanyId ?? scheduleCompanyId;

        // Fail closed: returns false if companyId is null/undefined
        return companyId === currentCompanyId;
    });
}

$ctrl.selectedPaySchedule = null;
$ctrl.selectedPayPeriod = null;
$ctrl.filterTarget = null;

if ($ctrl.selectedEntityName) {
    $ctrl.selectedEntity = {};
    $ctrl.selectedEntityName = "";
    $ctrl.selectedEntityDetails = "";
}

if ($ctrl.storedTab === 2) {
    $ctrl.filteredTableData = $ctrl.tableData.filter(payrollRun => {
        if (payrollRun.RunType !== "REGULAR") return false;

        const relatedPayPeriod = $ctrl.payPeriods.find(p => p.Id === payrollRun.PayPeriodId);
        return relatedPayPeriod?.PayScheduleId === $ctrl.selectedPaySchedule;
    });
}

$ctrl.selectedPayPeriod = null;
$ctrl.filterTarget = null;

if ($ctrl.selectedEntityName) {
    $ctrl.selectedEntity = {};
    $ctrl.selectedEntityName = "";
    $ctrl.selectedEntityDetails = "";
}

