payrollRunId = payrollRunId ?? ($ctrl.uiState.selectedEntity ?? $ctrl.selectedEntity)?.Id;

if (!payrollRunId) return;

const jobsMap = $ctrl.payrollRunReviewService.getCachedJobs(payrollRunId);
$ctrl.uiState.payroll_run.jobs = Object.values(jobsMap);

const hasPendingJobs = $ctrl.uiState.payroll_run.jobs.some(
    job => !["COMPLETED", "FAILED"].includes(job.status)
);

if (hasPendingJobs && $ctrl.uiState.isViewingPayrollRunReviews) {
    $ctrl.$timeout(() => $ctrl.handlers.payroll_run.setSelectedPayrollRunReviewJobs(), $ctrl.pollingService.payrollRunReview.POLLING_INTERVAL_MS);
}

if (!$ctrl.uiState.selectedEntity && !$ctrl.selectedEntity) {
    console.error($ctrl.en.global.notifications.payrollRun.errors.console.NOT_FOUND);
    $ctrl.utils.toast($ctrl.en.global.notifications.payrollRun.errors.toast.NOT_FOUND, "ERROR");
    return;
}

const payrollRunId = ($ctrl.uiState.selectedEntity ?? $ctrl.selectedEntity).Id;
const displayName = ($ctrl.uiState.selectedEntity ?? $ctrl.selectedEntity).DisplayName;

const confirmRes = await $ctrl.$modal.open("confirm-action-modal", {
    title: $ctrl.en.global.notifications.payrollRun.initiateReview.confirm.title,
    body: $ctrl.en.global.notifications.payrollRun.initiateReview.confirm.body,
    confirmButtonLabel: "Yes",
    cancelButtonLabel: "No"
});

if (!confirmRes || !["ok", "cancel"].includes(confirmRes.result)) return;

const encashAccrualBalances = confirmRes.result === "ok";

try {
    const jobData = await $ctrl.payrollRunReviewService.initiateReview(payrollRunId, encashAccrualBalances);

    $ctrl.payrollRunReviewService.cacheJobDetails(payrollRunId, jobData);
    $ctrl.handlers.payroll_run.setSelectedPayrollRunReviewJobs();

    $ctrl.utils.toast(
        $ctrl.en.global.notifications.payrollRun.initiateReview.info.INITIATE(displayName),
        "INFO"
    );

    $ctrl.pollingService.payrollRunReview.startPolling(payrollRunId);

} catch (error) {
    console.error($ctrl.en.global.notifications.payrollRun.initiateReview.error.console.FAILED(displayName), error);
    $ctrl.utils.toast(
        $ctrl.en.global.notifications.payrollRun.initiateReview.error.toast.FAILED(displayName),
        "ERROR"
    );
}

if (!row) return;

const { payrollRunId, jobId, status } = row;

if (!payrollRunId || !jobId) {
    console.error("Cannot navigate: Missing Run ID or Job ID.");
    return;
}

if (!["COMPLETED", "FAILED"].includes(status)) {
    $ctrl.utils.toast("Review is not yet ready. Please try again later.", "INFO");
    return;
}

if (status === "FAILED") {
    $ctrl.utils.toast("This Payroll Run Review job failed. Please generate a new review.", "INFO");
    return;
}

try {
    const stateParams = {
        id: payrollRunId,
        jobId: jobId,
        origin: "dashboard"
    };

    $ctrl.$state.go("review_payroll", stateParams);
} catch (error) {
    console.error("Error transitioning to 'review_payroll' state:", error);
}
